class ListNode {
  constructor(val) {
    this.val = val;
    this.next = null;
  }
}

function findMiddle(head) {
  let slow = head, fast = head;
  while (fast && fast.next) {
    slow = slow.next;
    fast = fast.next.next;
  }
  return slow;
}

let head = null;
for (const v of [5, 4, 3, 2, 1]) {
  const n = new ListNode(v);
  n.next = head;
  head = n;
}
console.log(findMiddle(head).val);

